janelz:{n:"Jan Elzinga",d:"c. 1877–1952 · Grouw",b:1877,x:1952,s:"h",p:["johannesje", "theodora"],r:["nl"],t:"Born at Grouw. A cattle farmer, he married Aaltje Postma at Rauwerderhem on 25 May 1905. He died at Assen on 24 August 1952, aged 76.",src:[["Marriage record, 1905", "https://www.openarchieven.nl/frl:9a9ce2a9-0b80-5c58-fd8b-edf9aa0c710f"], ["Death record, 1952", "https://www.openarchieven.nl/frl:6b9d4ad7-b880-161c-c68b-f9e695fc34a6"]]},
