jantje:{n:"Jantje Eelkes Roukema",d:"b. c. 1820 · Gorredijk",b:1820,s:"h",p:["eelke", "bontje"],r:["nl"],t:"The daughter of a Gorredijk skipper."},
johannesjans:{"n":"Johannes Jans Elzinga","d":"b. c. 1792 · Bozum","s":"h","p":["jansikkes","pietjel"],"r":["nl"],"b":1792,"t":"Born at Bozum about 1792, the son of Jan Sikkes, who died at Rauwerd in 1809, and Pietje Lucas. He was a farm hand (boerenknecht) at Roordahuizum when he married Trijntje Oeges Tuinstra on 20 May 1815, and was later a labourer at Idaard. His surname, Elzinga or Elsinga, was one of the names Frisians took after 1811.","src":[["Marriage, Idaarderadeel, 1815","https://www.openarchieven.nl/frl:6cf369ac-e86f-e02c-8906-f1d707c1a474"]]},
trijntje:{"n":"Trijntje Oeges Tuinstra","d":"c. 1793–1863 · Roordahuizum","s":"h","p":["oege","aukjejac"],"r":["nl"],"b":1793,"x":1863,"t":"Born at Roordahuizum about 1793, the daughter of Oege Tjerks Tuinstra, a labourer, and Aukje Jacobs. She was a farm maid (boerenmeid) at Akkrum when she married Johannes Jans Elsinga on 20 May 1815, aged 22. She died a widow at Huizum, by Leeuwarden, on 31 May 1863, aged 70.","src":[["Marriage, Idaarderadeel, 1815","https://www.openarchieven.nl/frl:6cf369ac-e86f-e02c-8906-f1d707c1a474"],["Death record, 1863","https://www.openarchieven.nl/frl:9faa0fdc-ee20-25c9-95c9-429be4a73d5d"]]},
eelke:{"n":"Eelke Wymers Roukema","d":"b. c. 1787 · Gorredijk","s":"h","p":["wymer","jantjepi"],"r":["nl"],"b":1787,"t":"Born at Gorredijk about 1787, the son of Wymer Eelkes Raukema and Jantje Pieters. A skipper (schipper) on the waterways of Opsterland, he married Bontje Harkes Landmeter of Lippenhuizen on 10 May 1817, when he was 30. He died before her.","src":[["Marriage, Opsterland, 1817","https://www.openarchieven.nl/frl:8f5bb7c9-bf13-8b99-362b-b6f2cdca6945"]]},
bontje:{"n":"Bontje Harkes Landmeter","d":"c. 1795–1864 · Lippenhuizen","s":"h","p":["harkel","grietjesy"],"r":["nl"],"b":1795,"x":1864,"t":"Born at Lippenhuizen in Opsterland about 1795, the daughter of Harke Kornelis Landmeter and Grietje Sytzes. On 10 May 1817, aged 22, she married Eelke Wymers Roukema, a skipper of Gorredijk. She outlived him and died a widow at Irnsum on 18 March 1864, aged 69.","src":[["Marriage, Opsterland, 1817","https://www.openarchieven.nl/frl:8f5bb7c9-bf13-8b99-362b-b6f2cdca6945"],["Death record, 1864","https://www.openarchieven.nl/frl:3d439f12-8ae0-9e41-7276-ba9284f07190"]]},
jouke:{n:"Jouke Klazes Stok",d:"c. 1824–1864 · Grouw",b:1824,x:1864,s:"h",p:["klaass", "dora"],r:["nl"],t:"Born at Grouw. Married Berber Hendriks Jonker at Idaarderadeel on 31 May 1849.",src:[["Marriage record, 1849", "https://www.openarchieven.nl/frl:5a083dc0-7882-a88e-2afa-6341ea982343"]]},
