johannac:{n:"Johanna Cornelia de Vries",d:"c. 1788–1860",b:1788,x:1860,s:"b",p:["gerardusdv", "idaj"],r:["nl"],t:"The daughter of Gerardus de Vries and Ida Jonkers. She married Bernardus van den Berg of Tilburg and died there on 22 January 1860, aged 72.",src:[["Death record, 1860", "https://www.openarchieven.nl/rat:ab7d4fe8-3861-11e0-bcd1-8edf61960649"]]},
gerardus:{n:"Gerardus Hamers",d:"c. 1799–1849",b:1799,x:1849,s:"b",p:["johanneshamers", "geertruij"],r:["nl"],t:"Of Tilburg, the son of Johannes Hamers and Geertruij Reijnen. On 25 November 1818, aged 19, he married Maria van Gestel, who was 33. Their daughter Maria Gertruda was born in 1829. He died at Tilburg on 6 December 1849, aged 50.",src:[["Marriage, 1818", "https://www.openarchieven.nl/rat:1d15bcae-3861-11e0-bcd1-8edf61960649"], ["Death record, 1849", "https://www.openarchieven.nl/rat:a6497d94-3861-11e0-bcd1-8edf61960649"]]},
